def process(stateWithMostTotalReports, cleanMsaIdentity) -> pd.DataFrame:
    import pandas as pd

    top_state = stateWithMostTotalReports.iloc[0]["state"]

    d = cleanMsaIdentity[cleanMsaIdentity["state"] == top_state].copy()
    if d.empty:
        # Surface diagnostic info if the state name doesn't match the MSA file naming
        return pd.DataFrame([
            {"error": "No MSA rows found for top state", "topState": top_state,
             "availableStatesInMsaData_sample": ", ".join(sorted(cleanMsaIdentity["state"].unique())[:10])}
        ])

    out = d.sort_values(["reports", "msa"], ascending=[False, True]).head(1)
    return out[["state", "msa", "reports"]]
